const prisma = new PrismaClient();

const buildExplanation = (company: string, group: string) =>
  `This ${group} question is included in ${company} software-engineer interview preparation. It evaluates practical reasoning, correctness, trade-offs, and communication.`;

const buildFollowUpQuestions = (item: QuestionSeed) => {
  const sameCompany = questionSeeds.filter(
    (candidate) => candidate.companySlug === item.companySlug
  );
  const currentIndex = sameCompany.findIndex(
    (candidate) => candidate.slug === item.slug
  );

  // Keep the exact same follow-up data shape as the working consolidated
  // interview seed: an array of question strings. The frontend already
  // understands this shape and can resolve the question text to its route.
  return [1, 2, 3]
    .map((offset) => sameCompany[(currentIndex + offset) % sameCompany.length])
    .filter(Boolean)
    .map((candidate) => candidate.question);
};

const buildMistakes = (question: string) => [
  `Giving a memorized answer without explaining the invariant, trade-off, or practical use case for: ${question}`,
  "Ignoring edge cases, complexity, testing, security, or failure handling.",
  "Choosing a technology before clarifying requirements and constraints.",
];

async function main() {
  console.log(`Starting company interview seed: ${questionSeeds.length} questions...`);
  let created = 0; let updated = 0; let failed = 0;
  const categoryCache = new Map<string, string>();
  const subcategoryCache = new Map<string, string>();

  for (let i = 0; i < questionSeeds.length; i += 1) {
    const item = questionSeeds[i];
    try {
      let categoryId = categoryCache.get(item.companySlug);
      if (!categoryId) {
        const category = await prisma.category.upsert({
          where: { slug: `${item.companySlug}-interview-questions` },
          update: { name: `${item.company} Interview Questions`, group: "Company Interviews", description: `${item.company} software engineer interview preparation.` },
          create: { name: `${item.company} Interview Questions`, slug: `${item.companySlug}-interview-questions`, group: "Company Interviews", description: `${item.company} software engineer interview preparation.` },
        });
        categoryId = category.id; categoryCache.set(item.companySlug, category.id);
      }
      const subSlug = `${item.companySlug}-${item.subcategory.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
      const subKey = `${item.companySlug}:${item.subcategory}`;
      let subcategoryId = subcategoryCache.get(subKey);
      if (!subcategoryId) {
        const sub = await prisma.subcategory.upsert({
          where: { categoryId_slug: { categoryId, slug: subSlug } },
          update: { name: item.subcategory },
          create: { name: item.subcategory, slug: subSlug, categoryId },
        });
        subcategoryId = sub.id; subcategoryCache.set(subKey, sub.id);
      }
      const existing = await prisma.interviewQuestion.findUnique({ where: { slug: item.slug }, select: { id: true } });
      await prisma.interviewQuestion.upsert({
        where: { slug: item.slug },
        update: { question: item.question, categoryId, subcategoryId, experienceLevel: item.experienceLevel, difficulty: item.difficulty, interviewType: item.interviewType, shortDescription: item.shortDescription, explanation: buildExplanation(item.company, item.subcategory), sampleAnswer: item.sampleAnswer, detailedAnswer: item.sampleAnswer, keyPoints: [item.subcategory, item.focus], commonMistakes: buildMistakes(item.question), followUpQuestions: buildFollowUpQuestions(item), tags: [item.company, "Software Engineer", item.subcategory], isPublished: true, seoTitle: `${item.company} ${item.question} | Software Engineer Interview`, seoDescription: `${item.company} software engineer interview preparation for ${item.question}, with explanation, trade-offs, testing, and follow-up topics.` },
        create: { question: item.question, slug: item.slug, categoryId, subcategoryId, experienceLevel: item.experienceLevel, difficulty: item.difficulty, interviewType: item.interviewType, shortDescription: item.shortDescription, explanation: buildExplanation(item.company, item.subcategory), sampleAnswer: item.sampleAnswer, detailedAnswer: item.sampleAnswer, keyPoints: [item.subcategory, item.focus], commonMistakes: buildMistakes(item.question), followUpQuestions: buildFollowUpQuestions(item), tags: [item.company, "Software Engineer", item.subcategory], isPublished: true, seoTitle: `${item.company} ${item.question} | Software Engineer Interview`, seoDescription: `${item.company} software engineer interview preparation for ${item.question}, with explanation, trade-offs, testing, and follow-up topics.` },
      });
      existing ? updated++ : created++;
      if ((i + 1) % 100 === 0 || i + 1 === questionSeeds.length) console.log(`Progress: ${i + 1}/${questionSeeds.length} | created=${created} updated=${updated} failed=${failed}`);
    } catch (error) {
      failed++; console.error(`Failed: ${item.company} | ${item.question}`); console.error(error);
    }
  }
  const published = await prisma.interviewQuestion.count({ where: { isPublished: true } });
  console.log(`Completed. Seed records=${questionSeeds.length}, created=${created}, updated=${updated}, failed=${failed}, publishedQuestionsInDb=${published}`);
  if (failed > 0) throw new Error(`${failed} question(s) failed to seed.`);
}

main().catch((error) => { console.error("Company interview seed failed:", error); process.exitCode = 1; }).finally(async () => { await prisma.$disconnect(); });